primary_key,
product,
part,
total_inventory,
lock_in_inventor
FROM ${tableName}
WHERE enterprise_code = #{enterpriseCode}
AND (
product IN

    #{materialCode}

OR part IN

    #{materialCode}

)

mapper.update:
UPDATE ${tableName}
SET lock_in_inventor = lock_in_inventor + #{lockInPart}
WHERE primary_key = #{inventoryRecordCode}
  AND enterprise_code = #{enterpriseCode}
  AND total_inventory - lock_in_inventor >= #{lockInPart}

mapper.select:
select t.primary_key stock, t.product_part_code, t.picture, t1.product_part_sign, t1.model, t1.pcs, t2.pieces_sign pcsChn, t.total_inventory, GREATEST(total_inventory - lock_in_inventor, 0) canUseInventory, t.shipping_space::BIGINT[] positionCodes, t.count_cycle, t.state, case when t.state then '启用' else '停用' end stateChn, t.safe_inventory, t.remark, t.stock_init_state, t.bar_code_number, t3.type_name, t3.primary_key productPartTypeCode, t3.attribute, t.check_version, t.check_flag, t.stocktaking_type, CASE WHEN EXISTS (SELECT 1 FROM ${positionStockBatchTableName} t4 WHERE t.primary_key = t4.stock_code and t.product_part_code = t4.product_or_part and t.shipping_space[1] = t4.position_code) THEN true ELSE false END AS haveBatchFlag, t.stock_limit from ${stockTableName} t left join ${productPartTableName} t1 on t.product_part_code = t1.primary_key left join ${piecesTableName} t2 on t1.pcs = t2.primary_key left join ${productPartTypeTableName} t3 on t1.product_part_type = t3.primary_key where t.delete_flag = false and t.enterprise_code = #{enterpriseCode}
and ${dynamicTableNameProxy.getXiHangPartQuery("t.product_part_code","xihang",requestData.partUnityNo)}
and t1.model LIKE '%'|| #{requestData.model} ||'%'
and t1.product_part_sign LIKE '%'|| #{requestData.productPartSign} ||'%'
AND (t1.model ilike '%' || #{requestData.searchName} || '%' or t1.product_part_sign ilike '%' || #{requestData.searchName} || '%')
and t.bar_code_number LIKE '%'|| #{requestData.barCodeNumber} ||'%'
and t3.attribute = #{requestData.attribute}
and t3.attribute in
#{code}
and t.product_part_code in
#{code}
and t.state = #{requestData.state}
and t.stock_init_state = #{requestData.stockInitState}
and t.primary_key in
#{code}
and t3.primary_key in
#{item}
and
#{value} = ANY (t.shipping_space)
and t1.attribute in
#{partAttributeRightJPA}
order by t.id desc
LIMIT #{requestData.pageSize} OFFSET #{requestData.offset}

select t1.unity_no as part_Unity_No, t4.bar_code_number, t1.product_part_sign, t1.model, t.position_codes::BIGINT[], t.total_inventory, t.check_total_inventory, t.disparity, t.check_operation, t.check_operation_name, t.check_time, t.stocktaking_type, t.check_version, t1.pcs, t3.pieces_sign as pcsChn, t.primary_key, t4.shipping_space::BIGINT[] positionCodes, t2.type_name, t1.attribute from ${stockCheckRecordTableName} t left join ${productPartTableName} t1 on t.product_part_code = t1.primary_key left join ${productPartTypeTableName} t2 on t1.product_part_type = t2.primary_key left join ${piecesTableName} t3 on t1.pcs = t3.primary_key left join ${stockTableName} t4 on t.stock_code = t4.primary_key where t.enterprise_code = #{enterpriseCode} and t.delete_flag = false and t.check_flag = true
AND (t1.model like '%' || #{requestData.searchName} || '%' or t1.product_part_sign like '%' || #{requestData.searchName} || '%')
and t4.bar_code_number LIKE '%'|| #{requestData.barCodeNumber} ||'%'
and t1.unity_no ilike '%'|| #{requestData.partUnityNo} ||'%'
and t1.attribute = #{requestData.attribute}
and t1.attribute in
#{code}
and t.stocktaking_type in
#{stocktakingType}
and
#{value} = ANY (t4.shipping_space)
and t2.primary_key in
#{item}
and t.check_operation in
#{code}
AND t.check_time >= #{requestData.startTime}
AND t.check_time <= #{requestData.endTime}
and t.primary_key in
#{code}
and t1.attribute in
#{partAttributeRightJPA}
order by t.check_time desc, t.id desc
LIMIT #{requestData.pageSize} OFFSET #{requestData.offset}

mapper.update:
update ${stockTableName}
set shipping_space = #{positionCodes,jdbcType=ARRAY,typeHandler=com.futurecraftsmen.pms.service.domain.ArrayTypeHandler}
where enterprise_code = #{enterpriseCode}
and primary_key in

    #{item}

mapper.select:
select t3.type_name, t1.product_part_sign, t1.model, t.bar_code_number, t2.pieces_sign pcsChn, t.total_inventory, t.total_inventory - t.lock_in_inventor canUseInventory, t.safe_inventory, t.count_cycle, t.remark, p.position_sign, ps.position_stock_num from ${stockTableName} t left join ${positionStockTableName} ps on ps.stock = t.primary_key left join ${positionTableName} p on ps.position_code = p.primary_key left join ${productPartTableName} t1 on t.product_part_code = t1.primary_key left join ${piecesTableName} t2 on t1.pcs = t2.primary_key left join ${productPartTypeTableName} t3 on t1.product_part_type = t3.primary_key where t.delete_flag = false and t.enterprise_code = #{enterpriseCode}
and t1.model LIKE '%'|| #{requestData.model} ||'%'
and t.state = #{requestData.state}
and t.stock_init_state = #{requestData.stockInitState}
and t.primary_key in
#{code}
order by t.create_time desc
